type Parsed { value: Int, pos: Int, dz: Bool }

fn is_digit_char(c: Str) -> Bool {
  return c.len() == 1 and "0123456789".contains(c)
}

fn tokenize(s: Str) -> Result[List[Str], Str] {
  let cs = s.chars()
  let n = cs.len()
  var toks: List[Str] = []
  var i = 0
  while i < n {
    let c = cs.get_or(i, "")
    if is_digit_char(c) {
      var num = ""
      while i < n and is_digit_char(cs.get_or(i, "")) {
        num = num + cs.get_or(i, "")
        i = i + 1
      }
      toks = toks.push(num)
    } else if c == " " {
      i = i + 1
    } else if "+-*/()".contains(c) {
      toks = toks.push(c)
      i = i + 1
    } else {
      return Err("syntax error")
    }
  }
  return Ok(toks)
}

fn parse_primary(toks: List[Str], p: Int) -> Result[Parsed, Str] {
  let t = toks.get_or(p, "")
  if is_digit_char(t.slice(0, 1)) {
    return Ok(Parsed { value: t.to_int().unwrap_or(0), pos: p + 1, dz: false })
  }
  if t == "(" {
    let inner = parse_expr(toks, p + 1)?
    if toks.get_or(inner.pos, "") != ")" {
      return Err("syntax error")
    }
    return Ok(Parsed { value: inner.value, pos: inner.pos + 1, dz: inner.dz })
  }
  return Err("syntax error")
}

fn parse_unary(toks: List[Str], p: Int) -> Result[Parsed, Str] {
  if toks.get_or(p, "") == "-" {
    let inner = parse_unary(toks, p + 1)?
    return Ok(Parsed { value: 0 - inner.value, pos: inner.pos, dz: inner.dz })
  }
  return parse_primary(toks, p)
}

fn parse_term(toks: List[Str], p: Int) -> Result[Parsed, Str] {
  let head = parse_unary(toks, p)?
  var acc = head.value
  var dz = head.dz
  var pos = head.pos
  while pos < toks.len() and (toks.get_or(pos, "") == "*" or toks.get_or(pos, "") == "/") {
    let op = toks.get_or(pos, "")
    let rhs = parse_unary(toks, pos + 1)?
    dz = dz or rhs.dz
    let d = rhs.value
    if op == "*" {
      acc = acc * d
    } else if d != 0 {
      acc = acc / d
    } else {
      dz = true
      acc = 0
    }
    pos = rhs.pos
  }
  return Ok(Parsed { value: acc, pos: pos, dz: dz })
}

fn parse_expr(toks: List[Str], p: Int) -> Result[Parsed, Str] {
  let head = parse_term(toks, p)?
  var acc = head.value
  var dz = head.dz
  var pos = head.pos
  while pos < toks.len() and (toks.get_or(pos, "") == "+" or toks.get_or(pos, "") == "-") {
    let op = toks.get_or(pos, "")
    let rhs = parse_term(toks, pos + 1)?
    dz = dz or rhs.dz
    if op == "+" {
      acc = acc + rhs.value
    } else {
      acc = acc - rhs.value
    }
    pos = rhs.pos
  }
  return Ok(Parsed { value: acc, pos: pos, dz: dz })
}

pub fn calc(expr: Str) -> Result[Int, Str] {
  let toks = tokenize(expr)?
  if toks.is_empty() {
    return Err("syntax error")
  }
  let r = parse_expr(toks, 0)?
  if r.pos != toks.len() {
    return Err("syntax error")
  }
  if r.dz {
    return Err("division by zero")
  }
  return Ok(r.value)
}
